        ledger.snapshot[p]={size:s.size,mtime:s.mtime};
      ledger.initialized=true;
      await plugin.persistTransport();
      await plugin.log('Windows 基线就绪','已记录 '+Object.keys(signatures).length+
        " 个既有交换文件。后续内容、普通 回执 统一进入一个增量 ZIP；无新内容时反馈暂存。");
