      if(names.has(rel.normalize('NFC').toLowerCase()))
        fail('去除知识库根目录后出现重复或大小写冲突路径：'+rel);
      names.add(rel.normalize('NFC').toLowerCase());
      const content=await readEntry(z),hash=await sha256(content);
