      const acks=new Set([...sender.receivedAcks,...receiver.generatedAcks].filter(a=>a.fromDeviceId===receiver.deviceId&&matches(p,a)).map(a=>a.ackId));
      const download=receiver.downloads.find(r=>r.type==='zip'&&r.sha256===p.sha256);
