    const safe=(path,role)=>typeof path==='string'&&new RegExp('^VaultRelay-Transfer/'+(role==='send-zip'?'outgoing/[^/\\\\:\\x00-\\x1f]+\\.zip':'inbox/[^/\\\\:\\x00-\\x1f]+\\.json')+'$','i').test(path)&&!path.split('/').some(n=>n==='.'||n==='..'||n.startsWith('.'));
