    const activePeers=queuePlan.v605Review?VR606.reviewPeers(p,plan):[];
    if(activePeers.length)modal._v607PeerDocs=activePeers;
    const peers=queuePlan.v605Review?activePeers:modal._v607PeerDocs||[];
